<?php
namespace App\Http\Controllers\Storefront\Concerns;
use App\Models\Part; use Illuminate\Database\Eloquent\Builder; use Illuminate\Http\Request;
trait BuildsStorefrontQueries { protected function storefrontQuery(Request $request): Builder { $query=Part::query()->with(['images','category','car'])->storefrontVisible()->searchStorefront($request->string('q')->toString())->partNumberSearch($request->string('part_number')->toString())->priceBetween($request->input('price_min'),$request->input('price_max')); $vehicleModel=trim($request->string('vehicle_model')->toString()); if($vehicleModel!==''){ foreach(preg_split('/\s+/',$vehicleModel)?:[] as $token){ $query->where(function(Builder $inner) use($token): void { $like='%'.$token.'%'; $inner->where('name','like',$like)->orWhereHas('car',function(Builder $carQuery) use($like): void { $carQuery->where('make','like',$like)->orWhere('model','like',$like)->orWhere('model_variant','like',$like)->orWhere('engine_code','like',$like); }); }); } } $category=trim($request->string('category')->toString()); if($category!==''){ $query->whereHas('category',fn(Builder $categoryQuery)=>$categoryQuery->where('slug',$category)->orWhere('name','like','%'.$category.'%')); } match($request->string('sort')->toString()){ 'price_asc'=>$query->orderByRaw('price is null')->orderBy('price'), 'price_desc'=>$query->orderByDesc('price'), 'name'=>$query->orderBy('name'), default=>$query->latest('updated_at'), }; return $query; } }
